CREATE TABLE IF NOT EXISTS organizations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(160) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE, email VARCHAR(320) NOT NULL, display_name VARCHAR(160), role VARCHAR(40) NOT NULL DEFAULT 'member', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (organization_id,email));
CREATE TABLE IF NOT EXISTS leads (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE, external_source VARCHAR(60), external_id VARCHAR(160), first_name VARCHAR(100), last_name VARCHAR(100), company_name VARCHAR(200), email VARCHAR(320), phone VARCHAR(40), source VARCHAR(80), status VARCHAR(40) NOT NULL DEFAULT 'new', score NUMERIC(5,2), metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (organization_id,external_source,external_id));
CREATE TABLE IF NOT EXISTS customer_profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE, lead_id UUID REFERENCES leads(id) ON DELETE SET NULL, lifecycle_stage VARCHAR(60), health_score NUMERIC(5,2), churn_risk NUMERIC(5,2), attributes JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS interactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE, lead_id UUID REFERENCES leads(id) ON DELETE SET NULL, channel VARCHAR(40) NOT NULL, direction VARCHAR(20), interaction_type VARCHAR(60), subject TEXT, transcript TEXT, occurred_at TIMESTAMPTZ, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE, lead_id UUID REFERENCES leads(id) ON DELETE SET NULL, file_name VARCHAR(255) NOT NULL, mime_type VARCHAR(120), storage_url TEXT, extracted_text TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS document_chunks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), document_id UUID NOT NULL REFERENCES documents(id) ON DELETE CASCADE, chunk_index INTEGER NOT NULL, content TEXT NOT NULL, embedding VECTOR(1536), metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(document_id,chunk_index));
CREATE TABLE IF NOT EXISTS agent_tasks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE, agent_name VARCHAR(100) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', correlation_id UUID, input JSONB NOT NULL DEFAULT '{}'::jsonb, output JSONB NOT NULL DEFAULT '{}'::jsonb, error JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS approvals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE, entity_type VARCHAR(80) NOT NULL, entity_id UUID NOT NULL, approval_type VARCHAR(80) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', requested_by UUID REFERENCES users(id) ON DELETE SET NULL, approved_by UUID REFERENCES users(id) ON DELETE SET NULL, payload JSONB NOT NULL DEFAULT '{}'::jsonb, decision_note TEXT, requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), decided_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS workflow_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE, workflow_key VARCHAR(100) NOT NULL, n8n_execution_id VARCHAR(120), status VARCHAR(30) NOT NULL DEFAULT 'running', correlation_id UUID, input JSONB NOT NULL DEFAULT '{}'::jsonb, output JSONB NOT NULL DEFAULT '{}'::jsonb, error JSONB, started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), finished_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS event_outbox (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id) ON DELETE CASCADE, event_name VARCHAR(120) NOT NULL, aggregate_type VARCHAR(80) NOT NULL, aggregate_id UUID, correlation_id UUID, payload JSONB NOT NULL DEFAULT '{}'::jsonb, status VARCHAR(30) NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, published_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_leads_org_status ON leads(organization_id,status);
CREATE INDEX IF NOT EXISTS idx_leads_org_score ON leads(organization_id,score DESC);
CREATE INDEX IF NOT EXISTS idx_workflow_runs_correlation ON workflow_runs(correlation_id);
CREATE INDEX IF NOT EXISTS idx_event_outbox_status ON event_outbox(status,created_at);
